-- The tables that used to live in SQLite, now in Supabase Postgres.
-- IDs are "generated by default" so the one-time move script can keep the old IDs.

create table events (
    id bigint generated by default as identity primary key,
    dedupe_key text not null unique,
    name text not null,
    start timestamptz not null,
    venue text not null,
    city text not null,
    url text not null,
    source text not null,
    source_type text not null,
    organizer text,
    category text,
    score integer not null,
    eligible boolean not null,
    score_reason text
);

create table dropped_events (
    id bigint generated by default as identity primary key,
    name text not null,
    url text not null,
    reason text not null
);

create table subscribers (
    id bigint generated by default as identity primary key,
    name text not null,
    email text not null,
    interests text not null,
    look_prompt text not null,
    days text[] not null,
    token text not null unique
);

create table sent_events (
    subscriber_id bigint not null,
    event_id bigint not null,
    primary key (subscriber_id, event_id)
);

create table pastes (
    id bigint generated by default as identity primary key,
    link text not null,
    caption text not null,
    name text not null,
    start timestamptz not null,
    venue text not null,
    city text not null,
    url text not null,
    source text not null,
    organizer text
);

create table ai_requests (
    day date not null
);

create table waiting_pastes (
    id bigint generated by default as identity primary key,
    link text not null,
    caption text not null,
    tries integer not null default 0
);

-- Row Level Security with no policies: Supabase's public API can read or write nothing here.
-- The server connects as the owner role, which is not limited by these rules.
alter table events enable row level security;
alter table dropped_events enable row level security;
alter table subscribers enable row level security;
alter table sent_events enable row level security;
alter table pastes enable row level security;
alter table ai_requests enable row level security;
alter table waiting_pastes enable row level security;
